data.definition:
flowchart TD
    A["Where does traffic enter?"] --> B{"Is it TCP or UDP\nwithout HTTP semantics?"}
    B -->|Yes| LB["Load Balancer\nLayer 4, VNet scope"]
    B -->|No| C{"Are users in one region\nor many?"}
    C -->|One region| D{"Need WAF, path routing,\nor TLS termination?"}
    D -->|Yes| AGW["Application Gateway\nLayer 7, regional"]
    D -->|No| LB
    C -->|Many regions| FD["Front Door\nLayer 7, global anycast"]
    FD --> WAF["WAF policy at the edge"]
    AGW --> WAF2["Regional WAF policy"]
